src='''def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    for dr, dc in ((1, 1), (1, -1)):
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color == bg or color == 0:
                    continue
                nr, nc = r + dr, c + dc
                if not (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == color):
                    continue
                pr, pc = r - dr, c - dc
                if 0 <= pr < h and 0 <= pc < w and grid[pr][pc] == color:
                    continue
                if r in (0, h - 1) or c in (0, w - 1):
                    continue
                endr, endc = r, c
                while 0 <= endr + dr < h and 0 <= endc + dc < w and grid[endr + dr][endc + dc] == color:
                    endr, endc = endr + dr, endc + dc
                for sr, sc, vr, vc in ((r, c, -dr, -dc), (endr, endc, dr, dc)):
                    cells = []
                    rr, cc = sr + vr, sc + vc
                    clear = True
                    while 0 <= rr < h and 0 <= cc < w:
                        if grid[rr][cc] != bg:
                            clear = False
                            break
                        cells.append((rr, cc))
                        rr, cc = rr + vr, cc + vc
                    if clear:
                        for rr, cc in cells:
                            out[rr][cc] = color
    return out
'''
